    # Implement required methods here
    def length(self):
        return len(self._elements)

    def contains(self, element):
        return element in self._elements

    def index_of(self, element):
        return self._elements.index(element)

    def count_of(self, element):
        return self._elements.count(element)

    def sub_list(self, start_index, end_index):
        return ImmutableList(self._elements[start_index:end_index])

    def concat(self, other_list):
        return ImmutableList(self._elements + other_list._elements)

    def reverse(self):
        return ImmutableList(self._elements[::-1])

    def sort(self):
        return ImmutableList(sorted(self._elements))

    def remove_all(self, element):
        return ImmutableList([x for x in self._elements if x != element])

    def insert_at(self, index, element):
        return ImmutableList(self._elements[:index] + (element,) + self._elements[index:])

    def replace_at(self, index, element):
        return ImmutableList(self._elements[:index] + (element,) + self._elements[index+1:])

    def remove_at(self, index):
        return ImmutableList(self._elements[:index] + self._elements[index+1:])

    def clear(self):
        return ImmutableList([])

    def to_list(self):
        return list(self._elements)

    def for_each(self, callback):
        for element in self._elements:
            callback(element)

    def max(self):
        return max(self._elements)

    def min(self):
        return min(self._elements)

    def sum(self):
        return sum(self._elements)
